(()=>{var __webpack_modules__={976(){eval("{document.addEventListener('DOMContentLoaded', () => {\n  const container = document.getElementById('constellation-canvas-container');\n  if (!container) return;\n\n  const width = window.innerWidth * 2;\n  const height = window.innerHeight * 3;\n\n  // Create canvas\n  const canvas = document.createElement('canvas');\n  canvas.width = width;\n  canvas.height = height;\n  container.appendChild(canvas);\n\n  const ctx = canvas.getContext('2d');\n  if (!ctx) {\n    console.error('2D context not supported');\n    return;\n  }\n\n  const numStars = 100;\n  const stars = [];\n  const maxDistance = 150;\n\n  for (let i = 0; i < numStars; i++) {\n    stars.push({\n      x: Math.random() * width,\n      y: Math.random() * height,\n      vx: (Math.random() - 0.5) * 0.5,\n      vy: (Math.random() - 0.5) * 0.5,\n    });\n  }\n\n  function animate() {\n    ctx.clearRect(0, 0, width, height);\n\n    // Update and draw stars\n    ctx.fillStyle = 'white';\n    for (let i = 0; i < numStars; i++) {\n      const star = stars[i];\n      star.x += star.vx;\n      star.y += star.vy;\n\n      if (star.x < 0 || star.x > width) star.vx *= -1;\n      if (star.y < 0 || star.y > height) star.vy *= -1;\n\n      ctx.beginPath();\n      ctx.arc(star.x, star.y, 2, 0, Math.PI * 2);\n      ctx.fill();\n    }\n\n    // Draw lines\n    for (let i = 0; i < numStars; i++) {\n      for (let j = i + 1; j < numStars; j++) {\n        const s1 = stars[i];\n        const s2 = stars[j];\n        const dx = s1.x - s2.x;\n        const dy = s1.y - s2.y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n\n        if (dist < maxDistance) {\n          ctx.beginPath();\n          ctx.moveTo(s1.x, s1.y);\n          ctx.lineTo(s2.x, s2.y);\n          ctx.strokeStyle = `rgba(255, 255, 255, ${1 - dist / maxDistance})`;\n          ctx.lineWidth = 0.5;\n          ctx.stroke();\n        }\n      }\n    }\n\n    requestAnimationFrame(animate);\n  }\n\n  animate();\n});\n\n\n//# sourceURL=webpack://website-personal/./src/scripts/constellation.js?\n}")}},__webpack_exports__={};__webpack_modules__[976]()})();